CREATE TABLE `companies` (
  `id` int(11) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `thumbnail` varchar(255) DEFAULT NULL,
  `coverimage` varchar(255) DEFAULT NULL,
  `descriptionHTML` longtext DEFAULT NULL,
  `descriptionMarkdown` longtext DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `phonenumber` varchar(255) DEFAULT NULL,
  `amountEmployer` int(11) DEFAULT NULL,
  `taxnumber` varchar(255) DEFAULT NULL,
  `statusCode` varchar(255) DEFAULT NULL,
  `userId` int(11) DEFAULT NULL,
  `censorCode` varchar(255) DEFAULT NULL,
  `file` longblob DEFAULT NULL,
  `allowPost` int(11) DEFAULT 5,
  `allowHotPost` int(11) DEFAULT 0,
  `allowCvFree` int(11) DEFAULT 5,
  `allowCV` int(11) DEFAULT 0,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

