CREATE TABLE `detailposts` (
  `id` int(11) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `descriptionHTML` longtext DEFAULT NULL,
  `descriptionMarkdown` longtext DEFAULT NULL,
  `categoryJobCode` varchar(255) DEFAULT NULL,
  `addressCode` varchar(255) DEFAULT NULL,
  `salaryJobCode` varchar(255) DEFAULT NULL,
  `amount` int(11) DEFAULT NULL,
  `categoryJoblevelCode` varchar(255) DEFAULT NULL,
  `categoryWorktypeCode` varchar(255) DEFAULT NULL,
  `experienceJobCode` varchar(255) DEFAULT NULL,
  `genderPostCode` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

