CREATE TABLE `chatmessages` (
  `id` int(11) NOT NULL,
  `senderId` int(11) DEFAULT NULL,
  `receiverId` int(11) DEFAULT NULL,
  `content` text DEFAULT NULL,
  `isRead` tinyint(4) DEFAULT 0,
